1	#!/usr/bin/env node
2	/**
3	 * POG2 CombatHUDBridge — Standalone Launcher
4	 * Boots the WebSocket bridge on port 8080 so unified_diagnostic.html can connect.
5	 * Run: npx tsx src/bridge_server.ts
6	 * 
7	 * In standalone mode, emits simulated tick data so the diagnostic UI
8	 * can render without the full PlayerAgent/SimulationHarness stack.
9	 */
10	
11	import { CombatHUDBridge } from './utils/CombatHUDBridge.js';
12	
13	async function main() {
14	    console.log(`\x1b[38;5;33m[ POG2 COMBAT HUD BRIDGE ]\x1b[0m`);
15	    console.log(`\x1b[38;5;244m─────────────────────────────────\x1b[0m`);
16	
17	    const bridge = CombatHUDBridge.getInstance();
18	
19	    console.log(`\x1b[32m✅ CombatHUDBridge active on ws://localhost:8080\x1b[0m`);
20	    console.log(`\x1b[36m   Health endpoint: http://localhost:8080/health\x1b[0m`);
21	    console.log(`\x1b[38;5;244m   Open unified_diagnostic.html in browser to connect.\x1b[0m`);
22	    console.log(`\x1b[38;5;244m─────────────────────────────────\x1b[0m\n`);
23	
24	    // Heartbeat: emit simulated state every 600ms so the UI stays alive
25	    let tick = 0;
26	    const archetypes = ['aggressive', 'defensive', 'balanced', 'evasive'];
27	    const phases = ['Smoke Phase', 'Shadow Phase', 'Blood Phase', 'Ice Phase', 'Zaros Phase'];
28	    const kernelPhases = ['STABLE', 'EXPLORING', 'FALSE_STABILITY', 'ANOMALY'];
29	    const abilities = ['Galeshot', 'Ricochet', 'Snap Shot', 'Rapid Fire', 'Bombardment', 'Shadow Tendrils'];
30	
31	    setInterval(() => {
32	        tick++;
33	        const adrenaline = Math.min(1000, Math.floor(Math.random() * 1000));
34	        const archetype = archetypes[Math.floor(tick / 10) % archetypes.length];
35	        const phase = phases[Math.floor(tick / 15) % phases.length];
36	        const kernel = kernelPhases[Math.floor(Math.random() * kernelPhases.length)];
37	        const nextAbility = abilities[Math.floor(Math.random() * abilities.length)];
38	
39	        bridge.updateState(
40	            adrenaline,
41	            archetype,
42	            `Tick ${tick}: auto-attack`,
43	            'PVME Nex Rotation',
44	            nextAbility,
45	            'ranged',
46	            phase,
47	            200000 - (tick * 100),
48	            kernel
49	        );
50	
51	        // Occasional hitsplat
52	        if (tick % 3 === 0) {
53	            const dmg = Math.floor(Math.random() * 800) + 100;
54	            bridge.hitsplat(dmg, Math.random() > 0.7 ? 'CRIT' : 'DAMAGE', 'nex');
55	        }
56	
57	        if (tick % 10 === 0) {
58	            console.log(`[Bridge] Tick ${tick} | Clients: check /health`);
59	        }
60	    }, 600);
61	
62	    process.on('SIGINT', () => {
63	        console.log('\n[Bridge] Shutting down...');
64	        process.exit(0);
65	    });
66	}
67	
68	main();
