1	#!/usr/bin/env node
2	/**
3	 * POG2 Sovereign Switchboard — Standalone Launcher
4	 * Boots the SwitchboardLimb WebSocket server on port 8788.
5	 * Run: npm run switchboard
6	 */
7	
8	import { SwitchboardLimb } from './monitor/SwitchboardLimb.js';
9	import { rsmvBridge } from './utils/RSMVBridge.js';
10	
11	const PORT = 8788;
12	
13	// Minimal orchestrator stub — accepts commands and echoes acknowledgement.
14	const minimalOrchestrator = {
15	    async run(intent: string) {
16	        console.log(`[SWITCHBOARD] Received intent: ${intent}`);
17	
18	        if (intent.startsWith('GET_LIVE_RSMV')) {
19	            const parts = intent.split(' ');
20	            const x = parseInt(parts[1] || '3200');
21	            const z = parseInt(parts[2] || '3200');
22	            const plane = parseInt(parts[3] || '0');
23	
24	            console.log(`[SWITCHBOARD] ⚡ Requesting LIVE RSMV Extraction at [${x}, ${z}, ${plane}]`);
25	            const result = await rsmvBridge.getCollision(x, z, plane);
26	
27	            if (result.ok) {
28	                return { ok: true, value: { type: 'LIVE_RSMV', ...result.value }, error: null };
29	            } else {
30	                return { ok: false, value: null, error: result.error.message };
31	            }
32	        }
33	
34	        return { ok: true, value: { data: `ACK: ${intent}` }, error: null };
35	    }
36	};
37	
38	async function main() {
39	    const switchboard = SwitchboardLimb.getInstance();
40	    switchboard.initialize();
41	
42	    try {
43	        const result = await switchboard.startWithGracefulPort(minimalOrchestrator, PORT);
44	        console.log(`\x1b[32m[SWITCHBOARD] ✅ Sovereign Bridge ACTIVE on ${result.url}\x1b[0m`);
45	        console.log(`\x1b[36m[SWITCHBOARD] rsmv SovereignBridge can now connect.\x1b[0m`);
46	    } catch (err: any) {
47	        console.error(`\x1b[31m[SWITCHBOARD] ❌ Failed to start: ${err.message}\x1b[0m`);
48	        process.exit(1);
49	    }
50	
51	    // Broadcast a tick every 600ms to keep connected clients alive
52	    setInterval(() => {
53	        switchboard.broadcast({ type: 'tick_event', tick: Date.now(), events: [] });
54	    }, 600);
55	
56	    process.on('SIGINT', async () => {
57	        console.log('\n[SWITCHBOARD] Closing DB substrates...');
58	        try {
59	            const { SovereignDBLifecycle } = await import('./utils/SovereignDBLifecycle.js');
60	            await SovereignDBLifecycle.getInstance().shutdown();
61	        } catch (err) {
62	            console.error(`[SWITCHBOARD] DB Lifecycle error: ${(err as Error).message}`);
63	        }
64	        console.log('[SWITCHBOARD] Shutting down...');
65	        process.exit(0);
66	    });
67	}
68	
69	main();

1	import { exec } from 'child_process';
2	import { promisify } from 'util';
3	import { Agent, fetch as undiciFetch } from 'undici';
4	import type { SovereignConfig } from '../config/SovereignConfig.js';
5	import {
6	    type Result,
7	    type ModelCallParams,
8	    type ModelResponse,
9	    type ModelExecutor,
10	    type ModelCallResult,
11	    ok,
12	    type AICapability,
13	    type AITaskType,
14	    type AIServiceType,
15	    YaoState
16	} from '../core/models.js';
17	import type { TernaryRouter } from '../routing/TernaryRouter.js';
18	import { TaskScheduler } from '../routing/TaskScheduler.js';
19	import { TrainingCollector, type ErrorFixRecord } from '../utils/TrainingCollector.js';
20	import { EndpointHealer } from '../utils/EndpointHealer.js';
21	import { ModelRolodex } from '../api/ai/ModelRolodex.js';
22	import type { QuotaTracker, QuotaProvider } from '../utils/QuotaTracker.js';
23	
24	import { ArchitectureDigest } from '../core/ArchitectureDigest.js';
25	import { createLogger } from "../utils/logger.js";
26	
27	const execAsync = promisify(exec);
28	const logger = createLogger('ModelClient');
29	
30	/**
31	 * ModelClient â€” Real API calls to local and cloud-based neural substrates.
32	 * NO MOCKS. NO FAKES. Real network calls with proper error handling.
33	 */
34	export class ModelClient implements ModelExecutor {
35	    private readonly trainingCollector: TrainingCollector;
36	    private readonly healer: EndpointHealer;
37	    private readonly digest: ArchitectureDigest;
38	    private readonly customAgent: Agent;
39	    private rolodex?: ModelRolodex;
40	    private quotaTracker?: QuotaTracker;
41	
42	    public async execute(params: ModelCallParams): Promise<Result<string>> {
43	        const result = await this.call(params);
44	        if (result.ok) {
45	            return { ok: true, value: result.value.response };
46	        }
47	        return { ok: false, error: result.error || new Error("Unknown model execution error") };
48	    }
49	
50	    constructor(
51	        public readonly config: SovereignConfig,
52	        private readonly router?: TernaryRouter
53	    ) {
54	        this.trainingCollector = TrainingCollector.getInstance();
55	        this.digest = new ArchitectureDigest(process.cwd());
56	        // Fallback to router's hexagram if available
57	        const hex = router?.getHexagram() || (globalThis as any).hexagram;
58	        this.healer = new EndpointHealer(hex, this.trainingCollector);
59	
60	        // Massive local contexts (33b+) may take over 5 mins to load into VRAM or stream.
61	        // Node's default fetch relies on Undici which enforces a strict 300_000ms headers timeout.
62	        // We override this to 24 hours (86,400,000ms) for high-fidelity local perseverance until complete.
63	        this.customAgent = new Agent({
64	            headersTimeout: 86_400_000,
65	            bodyTimeout: 86_400_000,
66	            connectTimeout: 120_000
67	        });
68	    }
69	
70	    public getRouter(): TernaryRouter | undefined {
71	        return this.router;
72	    }
73	
74	    public getHealer(): EndpointHealer {
75	        return this.healer;
76	    }
77	
78	    public getTrainingCollector(): TrainingCollector {
79	        return this.trainingCollector;
80	    }
81	
82	    /** Inject or retrieve the ModelRolodex for dynamic model discovery */
83	    public setRolodex(rolodex: ModelRolodex): void { this.rolodex = rolodex; }
84	    public getRolodex(): ModelRolodex | undefined { return this.rolodex; }
85	
86	    /** Inject QuotaTracker for free-tier FinOps tracking */
87	    public setQuotaTracker(qt: QuotaTracker): void { this.quotaTracker = qt; }
88	    public getQuotaTracker(): QuotaTracker | undefined { return this.quotaTracker; }
89	
90	    /** Check if the Ollama substrate is online */
91	    async checkHealth(): Promise<{ online: boolean; version: string }> {
92	        for (let attempt = 1; attempt <= 3; attempt++) {
93	            try {
94	                const resp = await undiciFetch(`${this.config.ollamaBaseUrl}/api/version`, {
95	                    signal: AbortSignal.timeout(15000)
96	                });
97	                if (resp.ok) {
98	                    const data = await resp.json() as { version?: string };
99	                    return { online: true, version: data.version || 'unknown' };
100	                }
101	            } catch {
102	                if (attempt === 3) return { online: false, version: 'unreachable' };
103	                await new Promise(res => setTimeout(res, 2000 * attempt));
104	            }
105	        }
106	        return { online: false, version: 'offline' };
107	    }
108	
109	    /** List locally available Ollama models */
110	    async listModels(): Promise<string[]> {
111	        for (let attempt = 1; attempt <= 3; attempt++) {
112	            try {
113	                const resp = await undiciFetch(`${this.config.ollamaBaseUrl}/api/tags`, {
114	                    signal: AbortSignal.timeout(15000)
115	                });
116	                if (resp.ok) {
117	                    const data = await resp.json() as { models?: Array<{ name: string }> };
118	                    return (data.models || []).map(m => m.name);
119	                }
120	            } catch {
121	                if (attempt === 3) return [];
122	                await new Promise(res => setTimeout(res, 2000 * attempt));
123	            }
124	        }
125	        return [];
126	    }
127	
128	
129	    /**
130	     * Implements ModelExecutor.callModel
131	     */
132	    async callModel(model: string, prompt: string, systemPrompt?: string, category?: string): Promise<ModelCallResult> {
133	        const result = await this.call({ model, prompt, systemPrompt, category });
134	        if (result.ok) {
135	            return { ok: true, value: { response: result.value.response } };
136	        }
137	        return { ok: false, value: { response: '' }, error: result.error };
138	    }
139	
140	    async call(params: ModelCallParams): Promise<Result<ModelResponse>> {
141	        const startTime = Date.now();
142	        let provider: 'ollama' | 'huggingface' | 'gemini' | 'cloudflare' | 'fireworks' | 'openrouter' | 'unknown' = 'ollama';
143	
144	        // Inject sovereign architectural constraints into all prompts
145	        const enforcedParams = {
146	            ...params,
147	            prompt: this.digest.inject(params.prompt)
148	        };
149	
150	        let result: Result<ModelResponse>;
151	
152	        const detectProvider = (model: string): string => {
153	            if (model.startsWith('gemini:')) return 'gemini';
154	            if (model.startsWith('huggingface:')) return 'huggingface';
155	            if (model.startsWith('fireworks:')) return 'fireworks';
156	            if (model.startsWith('openrouter:')) return 'openrouter';
157	            if (model.startsWith('@cf/') || model.includes('cloudflare')) return 'cloudflare';
158	            return 'ollama';
159	        };
160	
161	        provider = detectProvider(enforcedParams.model) as any;
162	        const priority = TaskScheduler.mapPriority(enforcedParams.yaoState || (globalThis as any).yaoState || YaoState.YoungYang);
163	        const timeout = this.getTimeoutByYaoState(enforcedParams.yaoState);
164	
165	        result = await TaskScheduler.getInstance().schedule(
166	            provider,
167	            priority,
168	            async () => {
169	                if (provider === 'gemini') {
170	                    return await this.callGemini(enforcedParams, startTime);
171	                } else if (provider === 'huggingface') {
172	                    return await this.callHuggingFace(enforcedParams, startTime);
173	                } else if (provider === 'fireworks') {
174	                    return await this.callFireworks(enforcedParams, startTime);
175	                } else if (provider === 'openrouter') {
176	                    return await this.callOpenRouter(enforcedParams, startTime);
177	                } else if (provider === 'cloudflare') {
178	                    return await this.callCloudflare(enforcedParams, startTime);
179	                } else {
180	                    return await this.callOllama(enforcedParams, startTime);
181	                }
182	            },
183	            timeout
184	        );
185	
186	        // Record interaction to D:\ training substrate (Skip for System Pulse)
187	        const latency = Date.now() - startTime;
188	        if (!enforcedParams.isSystemPulse) {
189	            this.trainingCollector.recordInteraction({
190	                model: enforcedParams.model,
191	                provider,
192	                category: enforcedParams.category as any,
193	                prompt: enforcedParams.prompt.substring(0, 2000),
194	                response: result.ok ? result.value.response.substring(0, 2000) : '',
195	                latencyMs: latency,
196	                tokenCount: result.ok ? result.value.tokensUsed : undefined,
197	                success: result.ok,
198	                error: result.ok ? undefined : result.error?.message
199	            }).catch(() => { /* non-blocking */ });
200	
201	            this.trainingCollector.recordMetric({
202	                model: enforcedParams.model,
203	                provider,
204	                latencyMs: latency,
205	                success: result.ok,
206	                tokenCount: result.ok ? result.value.tokensUsed : undefined
207	            }).catch(() => { /* non-blocking */ });
208	        }
209	
210	        // Phase 6: Update ModelRolodex with call metrics (Skip for System Pulse)
211	        if (this.rolodex && !enforcedParams.isSystemPulse) {
212	            this.rolodex.recordCallResult(
213	                enforcedParams.model,
214	                ModelRolodex.toRolodexProvider(provider),
215	                result.ok,
216	                latency,
217	                result.ok ? result.value.tokensUsed : undefined
218	            );
219	        }
220	
221	        // Sovereign FinOps: Record quota usage
222	        if (this.quotaTracker) {
223	            const quotaProvider = provider as QuotaProvider;
224	            const tokensUsed = result.ok ? (result.value.tokensUsed ?? 0) : 0;            this.quotaTracker.recordUsage(quotaProvider, tokensUsed, 1);
225	        }
226	
227	        return result;
228	    }
229	
230	    private getTimeoutByYaoState(yaoState?: YaoState): number {
231	        if (yaoState === undefined && (globalThis as any).yaoState !== undefined) {
232	            yaoState = (globalThis as any).yaoState;
233	        }
234	        if (yaoState === undefined) return 300_000; // Default 5 mins
235	
236	        switch (yaoState) {
237	            case YaoState.OldYang:   // 3: Deep metamorphic change
238	            case YaoState.OldMixed:  // 4: Chaotic complexity
239	                return 86_400_000;   // 24 hours for deep sovereignty
240	            case YaoState.YoungYin:
241	                return 180_000; // 3m fast response
242	            case YaoState.YoungYang: // 2: Stable expansion
243	            case YaoState.OldYin:    // 1: Structural break
244	                return 3_600_000;    // 1 hour
245	            case YaoState.YoungMixed:// 5: Emerging
246	                return 600_000;     // 10 mins
247	            default:
248	                return 300_000;
249	        }
250	    }
251	
252	    /**
253	     * Resilient Call: Automatically retries with a fallback model from the router if the first attempt fails.
254	     */
255	    async resilientCall(params: ModelCallParams & { maxRetries?: number }): Promise<Result<ModelResponse>> {
256	        let attempts = 0;
257	        const maxRetries = params.maxRetries ?? 2;
258	        let lastError: Error | undefined;
259	        let cascadeIndex = -1;
260	        let failoverSequence: string[] = [];
261	
262	        while (attempts <= maxRetries) {
263	            const result = await this.call(params);
264	            if (result.ok) return result;
265	
266	            lastError = result.error;
267	            attempts++;
268	
269	            if (attempts <= maxRetries && this.router) {
270	                logger.warn({ model: params.model, attempt: attempts }, 'Model call failed, seeking fallback...');
271	                this.router.recordFailure(params.model);
272	
273	                // Phase 2: If a tier is explicitly provided, use the tier's failover sequence directly
274	                if (params.tier) {
275	                    if (failoverSequence.length === 0) {
276	                        failoverSequence = Array.from(new Set(this.router.getFailoverSequence(params.tier)));
277	                        cascadeIndex = failoverSequence.indexOf(params.model);
278	                        if (cascadeIndex === -1) cascadeIndex = 0;
279	                    }
280	                    if (cascadeIndex < failoverSequence.length - 1) {
281	                        cascadeIndex++;
282	                        params = { ...params, model: failoverSequence[cascadeIndex] };
283	                        logger.info({ nextModel: params.model, tier: params.tier }, 'Tier-aware cascade to next substrate');
284	                    } else {
285	                        logger.error({ tier: params.tier }, 'All substrates in tier exhausted');
286	                        break;
287	                    }
288	                } else {
289	                    // Legacy Phase 72/76.3 logic: Deduplicate sequence and advance index explicitly
290	                    if (failoverSequence.length === 0) {
291	                        const currentComplexity = await this.router.classify(params.prompt);
292	                        const isMaster = params.model === this.config.masterReasoningModel || params.model === this.config.masterFallbackModel || params.model === this.config.masterLocalModel || params.model === this.config.orchestratorModel;
293	
294	                        const decision = await this.router.route(isMaster ? 'Orchestrator' : currentComplexity);
295	                        failoverSequence = Array.from(new Set(this.router.getFailoverSequence(decision.tier)));
296	                        cascadeIndex = failoverSequence.indexOf(params.model);
297	                    }
298	
299	                    if (cascadeIndex !== -1 && cascadeIndex < failoverSequence.length - 1) {
300	                        cascadeIndex++;
301	                        params = { ...params, model: failoverSequence[cascadeIndex] };
302	                        logger.info({ nextModel: params.model }, 'Cascading to next model in sequence');
303	                    } else {
304	                        // Fallback to standard routing if not in sequence or at end
305	                        const currentComplexity = await this.router.classify(params.prompt);
306	                        const newRoute = await this.router.route(currentComplexity);
307	                        if (newRoute.model === params.model) break;
308	                        params = { ...params, model: newRoute.model };
309	                    }
310	                }
311	            }
312	        }
313	
314	        // All retries exhausted Ã¢â‚¬â€ invoke EndpointHealer before final failure
315	        const provider: 'ollama' | 'huggingface' | 'gemini' | 'cloudflare' | 'fireworks' | 'openrouter' | 'unknown' = params.model.startsWith('gemini:') ? 'gemini'
316	            : params.model.startsWith('huggingface:') ? 'huggingface'
317	                : params.model.startsWith('fireworks:') ? 'fireworks'
318	                    : params.model.startsWith('openrouter:') ? 'openrouter'
319	                        : params.model.startsWith('@cf/') || params.model.includes('cloudflare') ? 'cloudflare'
320	                            : 'ollama';
321	        const diagnostic = await this.healer.diagnoseAndHeal(provider, lastError?.message || 'Unknown', params.model);
322	
323	        if (diagnostic.resolved) {
324	            // One final attempt after healing
325	            logger.info({ resolution: diagnostic.resolution }, 'EndpointHealer resolved issue Ã¢â‚¬â€ retrying...');
326	            const finalAttempt = await this.call(params);
327	
328	            // Phase 56: Persistent Training Loop - Record Error Fix
329	            this.trainingCollector.recordErrorFix({
330	                errorMessage: lastError?.message || 'Unknown',
331	                resolution: diagnostic.resolution,
332	                model: params.model,
333	                success: finalAttempt.ok
334	            }).catch(() => { /* Non-blocking training persistence */ });
335	
336	            if (finalAttempt.ok) return finalAttempt;
337	        }
338	
339	        return { ok: false, error: lastError || new Error('Max retries exceeded Ã¢â‚¬â€ EndpointHealer could not resolve') };
340	    }
341	
342	    async embed(text: string, modelOverride?: string): Promise<Result<Float32Array>> {
343	        const model = modelOverride || this.config.embeddingModel || 'qwen3-embedding:latest';
344	
345	        let result: Result<Float32Array>;
346	        if (model && model.startsWith('gemini:')) {
347	            result = await this.embedGemini(text);
348	        } else {
349	            result = await this.embedOllama(text, model);
350	            
351	            // Phase 108/114: Real Resilient Embedding Fallback
352	            if (!result.ok && this.config.secondaryCloudApiKey) {
353	                logger.warn({ model, error: result.error?.message }, 'Primary local embedding failed. Attempting Gemini fallback substrate...');
354	                const geminiFallback = await this.embedGemini(text);
355	                if (geminiFallback.ok) {
356	                    logger.info('Gemini embedding fallback successful.');
357	                    return geminiFallback;
358	                } else {
359	                    logger.error({ error: geminiFallback.error?.message }, 'Gemini embedding fallback also failed (Quota exhausted or network down).');
360	                }
361	            } else if (!result.ok) {
362	                 logger.error({ model, error: result.error?.message }, 'Primary local embedding failed. Gemini fallback disabled (No API Key).');
363	            }
364	        }
365	
366	        return result;
367	    }
368	
369	    private async callGemini(params: ModelCallParams, startTime: number): Promise<Result<ModelResponse>> {
370	        const apiKey = this.config.secondaryCloudApiKey;
371	        if (!apiKey) {
372	            return { ok: false, error: new Error('SECONDARY_CLOUD_API_KEY not set Ã¢â‚¬â€ cannot call cloud substrate') };
373	        }
374	
375	        // Tiered Gemini Fallback Sequence
376	        const primaryModelId = params.model.replace('gemini:', '');
377	        const fallbackSequence = [
378	            primaryModelId,
379	            this.config.geminiFlashModel,
380	            'gemini-1.5-flash-001',
381	            this.config.geminiProModel
382	        ];
383	
384	        // Deduplicate
385	        const uniqueSequence = Array.from(new Set(fallbackSequence));
386	        let lastError: Error | undefined;
387	
388	        for (const modelId of uniqueSequence) {
389	            const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent?key=${apiKey}`;
390	
391	            const messages: Array<{ role: string; parts: Array<{ text: string }> }> = [];
392	
393	            if (params.systemPrompt) {
394	                messages.push({ role: 'user', parts: [{ text: params.systemPrompt }] });
395	                messages.push({ role: 'model', parts: [{ text: 'Understood.' }] });
396	            }
397	
398	            messages.push({ role: 'user', parts: [{ text: params.prompt }] });
399	
400	            const body = {
401	                contents: messages,
402	                generationConfig: {
403	                    temperature: params.temperature ?? 0.3,
404	                    maxOutputTokens: params.maxTokens ?? 8192
405	                }
406	            };
407	
408	            try {
409	                let response = await undiciFetch(url, {
410	                    method: 'POST',
411	                    headers: { 'Content-Type': 'application/json' },
412	                    body: JSON.stringify(body),
413	                    signal: AbortSignal.timeout(this.getTimeoutByYaoState(params.yaoState))
414	                });
415	
416	                if (!response.ok) {
417	                    const errorText = await response.text();
418	
419	                    // If 404, try next model in sequence
420	                    if (response.status === 404) {
