138	    /** 
139	     * Sovereign FinOps / Hive Mind: Merge incoming state from the Globe substrate.
140	     * Aggregates success/failure counts instead of overwriting, allowing multiple 
141	     * instances to share learned reputation scores offline and online.
142	     */
143	    public deserializeAndMerge(remoteState: RolodexState): void {
144	        let mergedCount = 0;
145	
146	        // Merge Models (The Reputation Score)
147	        for (const [key, remoteModel] of Object.entries(remoteState.models)) {
148	            if (!this.state.models[key]) {
149	                this.state.models[key] = { ...remoteModel };
150	                mergedCount++;
151	            } else {
152	                const localModel = this.state.models[key];
153	                // Only aggregate if the remote state has actually seen usage
154	                if (remoteModel.successCount + remoteModel.failureCount > 0) {
155	                    // We don't want to double-count our own updates if they echo back.
156	                    // A true CRDT is better, but a simplistic Max(local, remote) or addition 
157	                    // works for basic reputation sharing until we build an event-sourced log.
158	                    // For now, if remote has higher total interaction, we absorb the difference.
159	                    const localTotal = localModel.successCount + localModel.failureCount;
160	                    const remoteTotal = remoteModel.successCount + remoteModel.failureCount;
161	
162	                    if (remoteTotal > localTotal) {
163	                        localModel.successCount = Math.max(localModel.successCount, remoteModel.successCount);
164	                        localModel.failureCount = Math.max(localModel.failureCount, remoteModel.failureCount);
165	                        localModel.totalTokensUsed = Math.max(localModel.totalTokensUsed, remoteModel.totalTokensUsed);
166	                        localModel.avgLatencyMs = Math.round((localModel.avgLatencyMs + remoteModel.avgLatencyMs) / 2);
167	                        mergedCount++;
168	                    }
169	                }
170	                // Always sync the lastSeen timestamp if remote is newer
171	                if (remoteModel.lastSeen > localModel.lastSeen) {
172	                    localModel.lastSeen = remoteModel.lastSeen;
173	                }
174	            }
175	        }
176	
177	        // Merge Providers (Auth status and discovered models)
178	        for (const [key, remoteIdentity] of Object.entries(remoteState.providers)) {
179	            const pKey = key as RolodexProvider;
180	            const localIdentity = this.state.providers[pKey];
181	
182	            // If remote is authenticated and we aren't, absorb their model list (but not their account/email/keys)
183	            // This allows an offline node to know what models exist on a provider even if it can't reach the discovery API.
184	            if (remoteIdentity.authenticated) {
185	                const newModels = remoteIdentity.models.filter(m => !localIdentity.models.includes(m));
186	                if (newModels.length > 0) {
187	                    localIdentity.models.push(...newModels);
188	                }
189	            }
190	        }
191	
192	        if (mergedCount > 0) {
193	            logger.debug({ mergedModels: mergedCount }, 'Rolodex merged state from Hive Mind');
194	            this.persist(); // Save to local disk immediately upon beneficial merge
195	        }
196	    }
