378	        // ðŸ§¬ Phase 108: Physiological clamping (Prevent drift chaos)
379	        entry.reputation = Math.max(0.2, Math.min(2.0, entry.reputation + adjustment));
380	
381	        logger.info({
382	            model: modelId,
383	            provider,
384	            oldRep: oldRep.toFixed(4),
