1016	export const resolveCapability = (tier: string, rolodex: ModelRolodex, config: SovereignConfig): { model: string; ctx: number; reputation: number } | null => {
1017	    const cap = getCapability(tier);
1018	    if (!cap) return null;
1019	
1020	    // Preferred
1021	    if (rolodex.isModelHealthy(cap.preferredModel)) {
1022	        const key = `ollama:${cap.preferredModel}`;
1023	        const rep = rolodex.state.models[key]?.reputation ?? 1.0;
1024	        if (rep > 0.3) return { model: cap.preferredModel, ctx: cap.minCtx, reputation: rep };
1025	    }
1026	
1027	    // Fallback chain
1028	    for (const fb of cap.fallbackModels) {
1029	        if (fb === cap.preferredModel) continue;
1030	        if (rolodex.isModelHealthy(fb)) {
1031	            const key = `ollama:${fb}`;
1032	            const rep = rolodex.state.models[key]?.reputation ?? 0.5;
1033	            if (rep > 0.2) {
1034	                logger.info({ tier, fallback: fb }, 'Capability fallback');
1035	                return { model: fb, ctx: cap.minCtx, reputation: rep };
1036	            }
1037	        }
1038	    }
1039	
1040	    // Emergency: any healthy text model
1041	    const emergency = rolodex.getAllModels()
1042	        .filter(m => m.provider === 'ollama' && m.taskType === 'text' && m.reputation > 0.2)
1043	        .sort((a, b) => b.reputation - a.reputation)[0];
1044	
1045	    if (emergency) {
1046	        logger.warn({ tier, emergency: emergency.id }, 'Emergency fallback');
1047	        return { model: emergency.id, ctx: 4096, reputation: emergency.reputation };
1048	    }
1049	
1050	    return null;
1051	};
